# -*- coding: utf-8 -*-
"""Bir belgedeki jetonların (CLI bayrakları, BÜYÜK HARFLİ sözcükler, ters tırnaklı terimler) kılavuzda geçip geçmediğini denetler.
Kullanım: belge_jeton.py <belge-yolu> [--en-az N] [--tum]"""
import collections, os, re, sys
sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
KITAP = os.path.join(KOK, "docs", "tasarim", "uXBasic_Hedeflenen_Sistem_ve_Kullanma_Kilavuzu_V2_TR.md")
kitap = open(KITAP, encoding="utf-8").read()
kitap_k = kitap.lower()
belge = sys.argv[1]
if not os.path.isabs(belge):
    belge = os.path.join(KOK, belge)
metin = open(belge, encoding="utf-8", errors="replace").read()
en_az = 1
if "--en-az" in sys.argv:
    en_az = int(sys.argv[sys.argv.index("--en-az") + 1])
SAYAC = collections.Counter()
for m in re.finditer(r"(?<![\w-])--[a-z][a-z0-9-]{2,}", metin):
    SAYAC[("bayrak", m.group(0))] += 1
for m in re.finditer(r"\b[A-Z][A-Z0-9_]{3,}\b", metin):
    SAYAC[("SÖZCÜK", m.group(0))] += 1
for m in re.finditer(r"`([^`\n]{2,40})`", metin):
    t = m.group(1).strip()
    if re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.]{2,}(\(\))?", t):
        SAYAC[("terim", t.rstrip("()"))] += 1
yok = []
for (tur, j), n in SAYAC.items():
    if n < en_az:
        continue
    if j.lower() not in kitap_k:
        yok.append((tur, j, n))
print(f"{os.path.basename(belge)}: {len(SAYAC)} farklı jeton; kitapta OLMAYAN: {len(yok)}")
for tur in ("bayrak", "SÖZCÜK", "terim"):
    liste = sorted([x for x in yok if x[0] == tur], key=lambda x: (-x[2], x[1]))
    if liste:
        print(f"  [{tur}] ({len(liste)}):", ", ".join(f"{j}×{n}" if n > 1 else j for _, j, n in liste[:200]))

