    for (m, e, y), n in sorted(sayac.items()):
        print(f"  {m:<5} {e} -> {y}: {n}")
    if "--ayrinti" in sys.argv:
        for d, m, e, y, c in sorted(satirlar):
            print(f"- {d.replace('docs/kitaplar/_ortak/ornekler/', '')}  [{m}] {e} -> {y}   {str(c)[:140]}")


