    @{name='NATIVE'; args=@('bld', $managedSource, '--build-x64'); diagnosticTarget='NATIVE'},
    @{name='JS'; args=@('jsw', $managedSource)},
    @{name='WAT'; args=@('wat', $managedSource)},
    @{name='WASM'; args=@('wat', $managedSource, '--emit-wasm'); diagnosticTarget='WAT'}
)
