param([int]$IzlenenPid, [double]$EsikGB = 1.2, [string]$Log)
# C: boş alanı eşiğin altına inerse izlenen süreç ağacını durdurur (2026-10-13: CLI taraması 1 GB build\ ağacı bırakınca disk 2 GB'a düşmüştü)
function G($m) { ("{0}  {1}" -f (Get-Date -Format 'HH:mm:ss'), $m) | Add-Content -Path $Log -Encoding UTF8 }
G "bekçi başladı: izlenen PID $IzlenenPid, eşik $EsikGB GB"
while ($true) {
  $p = Get-Process -Id $IzlenenPid -ErrorAction SilentlyContinue
  if (-not $p) { G 'izlenen süreç bitti; bekçi çıkıyor'; break }
  $bos = (Get-PSDrive C).Free / 1GB
  if ($bos -lt $EsikGB) {
    G ("ALARM: C: boş {0:N2} GB < {1} GB; PID {2} durduruluyor" -f $bos, $EsikGB, $IzlenenPid)
    taskkill /PID $IzlenenPid /T /F | Out-Null
    G 'durduruldu'
    break
  }
  Start-Sleep -Seconds 15
}

