# -*- coding: utf-8 -*-
"""281 örneğin motor başına durum sayıları: eski (web_20261007 + kv birleşimi) ↔ yeni (1704 arşivi)."""
import json, os, re, sys, glob
from collections import Counter
sys.stdout.reconfigure(encoding="utf-8")
KOK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
ORTAK = os.path.join(KOK, "docs", "kitaplar", "_ortak")


def yukle(adlar):
    s = {}
    for ad in adlar:
        p = os.path.join(ORTAK, ad)
        if os.path.exists(p):
            for r in json.load(open(p, encoding="utf-8")):
                s[r["dosya"]] = r
    return s


eski = yukle(["ornek_sonuclari_web_20261007.json", "ornek_sonuclari_kv.json"])
yeni = yukle(["ornek_sonuclari_web_20261013_1704.json"])
# kitapta anılan örnekler
kitap = set()
for f in glob.glob(os.path.join(KOK, "tools", "kitap", "kilavuz_v2", "sablon", "*.md")):
    for m in re.finditer(r"\{\{ORNEK:([^|}]+)", open(f, encoding="utf-8").read()):
        kitap.add(m.group(1))
print("kitapta anılan örnek:", len(kitap))


def ozet(ad, S, sadece_kitap):
    sayac = {m: Counter() for m in ("AST", "MIR", "x64", "JS", "WASM")}
    uc = bek = 0
    for d, r in S.items():
        anahtar = d.split("ornekler/")[-1].replace(".uxb", "")
        if sadece_kitap and anahtar not in kitap:
            continue
        for m in sayac:
            v = r["motor"].get(m)
            if v:
                sayac[m][v["durum"]] += 1
        if r.get("has_oracle", bool(r.get("beklenen"))):
            bek += 1
            if all(r["motor"].get(k, {}).get("durum") == "GECTI" for k in ("AST", "MIR", "x64")):
                uc += 1
    print(f"\n== {ad} ({'yalnız kitap' if sadece_kitap else 'tüm örnekler'}) ; beklentili: {bek}; AST+MIR+x64 üçünde geçen: {uc}")
    for m, c in sayac.items():
        print(f"  {m:<5}", dict(c))


for kit in (False, True):
    ozet("10-07", eski, kit)
    ozet("1704", yeni, kit)

