(os.rmdir hedefe dokunmaz), depo içeriğinin değişmediğini doğrular, sonra kalan gerçek klasörleri siler."""
import os, shutil, stat, sys
sys.stdout.reconfigure(encoding="utf-8")
SP = r"C:\Users\mete\AppData\Local\Temp\claude\C--Users-mete-Downloads-BasicOyunSource-UXBc-Clean-UXBc-uxb\b85b832d-c86f-49e6-b0a0-47af736f8686\scratchpad"
K = os.path.join(SP, "sahte_kok")
DEPO = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb"
ADLAR = ["bin", "dist", "docs", "include", "libsx", "runtime", "tests", "tools"]


def baglanti_mi(yol):
    try:
        a = os.lstat(yol)
        return bool(getattr(a, "st_file_attributes", 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT)
    except OSError:
        return False


def say(yol):
    n = 0
    for _, d, f in os.walk(yol):
        n += len(d) + len(f)
    return n


assert os.path.abspath(K).startswith(os.path.abspath(SP) + os.sep), "yol scratchpad dışında"
if not os.path.exists(K):
    print("sahte_kok yok")
    sys.exit(0)
once = {a: len(os.listdir(os.path.join(DEPO, a))) for a in ADLAR}
once_derin = {a: say(os.path.join(DEPO, a)) for a in ("docs", "tools", "tests")}
print("önce  (üst düzey):", once)
print("önce  (derin sayı):", once_derin)
for ad in os.listdir(K):
    yol = os.path.join(K, ad)
    if baglanti_mi(yol):
        os.rmdir(yol)          # bağlantıyı kaldırır; hedef klasöre dokunmaz
        print("bağlantı kaldırıldı:", ad)
sonra = {a: len(os.listdir(os.path.join(DEPO, a))) for a in ADLAR}
sonra_derin = {a: say(os.path.join(DEPO, a)) for a in ("docs", "tools", "tests")}
print("sonra (üst düzey):", sonra)
print("sonra (derin sayı):", sonra_derin)
if once != sonra or once_derin != sonra_derin:
    print("UYARI: depo içeriği değişti — silme DURDURULDU")
    sys.exit(2)
kalan = []
for kok, dizinler, dosyalar in os.walk(K):
    for ad in dizinler + dosyalar:
        if baglanti_mi(os.path.join(kok, ad)):
            kalan.append(os.path.join(kok, ad))
print("kalan bağlantı sayısı:", len(kalan))
if kalan:
    print("UYARI: kalan bağlantılar var — silme DURDURULDU:", kalan[:5])
    sys.exit(3)
shutil.rmtree(K)
print("sahte_kok silindi")
print("kitap duruyor:", os.path.exists(os.path.join(DEPO, "docs", "tasarim", "uXBasic_Hedeflenen_Sistem_ve_Kullanma_Kilavuzu_V2_TR.md")))

