# -*- coding: utf-8 -*-
"""Oturumun scratchpad'indeki ESKİ deneme çıktı klasörlerini siler (yalnız adı listede olanlar; bağlantı içeriyorsa atlar)."""
import os, shutil, stat, sys
sys.stdout.reconfigure(encoding="utf-8")
SP = r"C:\Users\mete\AppData\Local\Temp\claude\C--Users-mete-Downloads-BasicOyunSource-UXBc-Clean-UXBc-uxb\b85b832d-c86f-49e6-b0a0-47af736f8686\scratchpad"
ADLAR = ["legacy_test", "cli_tarama3", "testkos", "cli_tarama2", "cli_tarama_depo_deneme", "legacy_test2", "tarif_dene_1", "cli_tarama"]


def baglanti_mi(yol):
    try:
        return bool(getattr(os.lstat(yol), "st_file_attributes", 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT)
    except OSError:
        return False


def boyut(yol):
    t = 0
    for kok, _, dosyalar in os.walk(yol):
        for f in dosyalar:
            try:
                t += os.lstat(os.path.join(kok, f)).st_size
            except OSError:
                pass
    return t


toplam = 0
for ad in ADLAR:
    yol = os.path.join(SP, ad)
    if not os.path.isdir(yol):
        print("yok:", ad)
        continue
    assert os.path.abspath(yol).startswith(os.path.abspath(SP) + os.sep)
    bag = [os.path.join(k, a) for k, d, f in os.walk(yol) for a in d + f if baglanti_mi(os.path.join(k, a))]
    if bag:
        print("ATLANDI (bağlantı var):", ad, bag[:2])
        continue
    b = boyut(yol)
    shutil.rmtree(yol)
    toplam += b
    print(f"silindi: {ad}  {b / 1048576:.0f} MB")
print(f"toplam {toplam / 1048576:.0f} MB")

