E = json.load(open(sys.argv[1], encoding="utf-8"))
Y = json.load(open(sys.argv[2], encoding="utf-8"))
print("eski:", E["ikili"].split("\\")[-1], E["zaman"], "| yeni:", Y["ikili"].split("\\")[-1], Y["zaman"])


def durum(r):
    if not r.get("var"):
        return "YOK"
    return "BOS" if r.get("tur") == "bos" else "OK:" + r.get("tur", "?")


# ---- A: dosya çıktılı seçenekler
fark = defaultdict(list)
for o in E["A"]:
    for f in E["A"][o]:
        e, y = E["A"][o][f], Y["A"].get(o, {}).get(f)
        if y is None:
            continue
        if e["kod"] != y["kod"] or durum(e) != durum(y):
            fark[(durum(e), e["kod"], durum(y), y["kod"])].append((o, f))
print("\n== A (dosya çıktılı) değişen seçenek×fiil:", sum(len(v) for v in fark.values()))
for (de, ke, dy, ky), liste in sorted(fark.items(), key=lambda x: -len(x[1])):
    secenekler = sorted({o for o, _ in liste})
    fiiller = sorted({f for _, f in liste})
    print(f"  eski [{de}, çıkış {ke}] -> yeni [{dy}, çıkış {ky}] : {len(liste)} hücre; seçenek {len(secenekler)}: {', '.join(secenekler[:8])}{' …' if len(secenekler) > 8 else ''}; fiiller: {', '.join(fiiller)}")

