for o in bf:
    for f in E["B"][o]:
        e, y = E["B"][o][f], Y["B"].get(o, {}).get(f)
        if y is None:
            continue
        if e["kod"] != y["kod"] or sorted(e["dosyalar"]) != sorted(y["dosyalar"]):
            degisen.append((o, f, e["kod"], y["kod"], len(e["dosyalar"]), len(y["dosyalar"])))
print("\n== B (bayrak) çıkış kodu ya da dosya kümesi değişen:", len(degisen))
for x in degisen[:25]:
    print("  ", x)
tb_e, tb_y = E["B"]["taban"], Y["B"]["taban"]
print("\ntaban dosya sayıları (eski → yeni):", {f: (len(tb_e[f]["dosyalar"]), len(tb_y[f]["dosyalar"])) for f in tb_e})

