"""281 örneğin (kitapta anılmayanlar dahil) eski (web_20261007 + kv) ↔ yeni sonuç farkı. Kullanım: ornek_tum_fark.py yeni.json"""
import json, os, sys
sys.stdout.reconfigure(encoding="utf-8")
ORTAK = r"C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb\docs\kitaplar\_ortak"


def yukle(adlar):
    s = {}
    for ad in adlar:
        p = ad if os.path.isabs(ad) else os.path.join(ORTAK, ad)
        if os.path.exists(p):
            for r in json.load(open(p, encoding="utf-8")):
                s[r["dosya"]] = r
    return s


E = yukle(["ornek_sonuclari_web_20261007.json", "ornek_sonuclari_kv.json"])
Y = yukle([sys.argv[1]])
n = 0
for d in sorted(Y):
    if d not in E:
        print("yeni örnek:", d)
        continue
    for m in ("AST", "MIR", "x64", "JS", "WASM"):
        e, y = E[d]["motor"].get(m), Y[d]["motor"].get(m)
        if e and y and e["durum"] != y["durum"]:
            n += 1
            print(f"{d.split('ornekler/')[-1]:<52} {m:<5} {e['durum']:<9} -> {y['durum']:<9} {' | '.join(str(x) for x in y['cikti'][:2])[:110]}")
print("değişen hücre:", n)

