param(
  [string]$Ik = 'uxb_kilavuz_20261014_0253.exe',
  [string]$Et = '0253',
  [string]$Adimlar = 'matris,ornek,vaka,tarif,arac,kararlilik,x64a,astx64,cli,model'
)
# Aday referans ikili için tam ölçüm hattı (ardışık, disk bekçili, sonuç dosyası varsa adımı atlar -> yeniden başlatılabilir).
# Sıra: kitap geçişi için kritik olanlar önce (matris, örnek, külliyat), sonra ek doğrulamalar, en sona disk yiyen model testleri.
$sp = 'C:\Users\mete\AppData\Local\Temp\claude\C--Users-mete-Downloads-BasicOyunSource-UXBc-Clean-UXBc-uxb\b85b832d-c86f-49e6-b0a0-47af736f8686\scratchpad'
$kok = 'C:\Users\mete\Downloads\BasicOyunSource\UXBc_Clean\UXBc\uxb'
$g = "$sp\gorunum"
$log = "$g\ardisik5_$Et.log"
function G($m) { ("{0}  {1}" -f (Get-Date -Format 'HH:mm:ss'), $m) | Add-Content -Path $log -Encoding UTF8 }
function Bos() { '{0:N2}' -f ((Get-PSDrive C).Free / 1GB) }
Set-Location $kok
Start-Process -FilePath 'pwsh' -ArgumentList @('-NoProfile', '-File', "$sp\disk_bekci.ps1", '-IzlenenPid', $PID, '-EsikGB', '1.2', '-Log', "$g\bekci5_$Et.log") -WindowStyle Hidden | Out-Null
G ("hat başladı (PID $PID): $Ik, adımlar=$Adimlar; C: boş $(Bos) GB")
$adim = $Adimlar.Split(',')
function Adim($ad, $cikti, [scriptblock]$is) {
  if ($adim -notcontains $ad) { return }
  if ($cikti -and (Test-Path $cikti)) { G "ADIM $ad zaten var; atlandı ($cikti)"; return }
  G "ADIM $ad başlıyor"
  $t0 = Get-Date
  & $is
  G ("ADIM $ad bitti: {0} dk; C: boş {1} GB" -f [int]((Get-Date) - $t0).TotalMinutes, (Bos))
}

Adim 'matris' "$g\matris_${Et}_ktip_dene3.json" {
  pwsh -NoProfile -File "$sp\ktip_matris2.ps1" -Ik $Ik -Etiket $Et
}
Adim 'ornek' "$g\ornek_${Et}_web.json" {
  python tools\kitap\ornek_dogrula.py --uxb "bin\$Ik" --web --is 4 --sonuc "$g\ornek_${Et}_web.json" *> "$g\ornek_${Et}_web.log"
}
Adim 'vaka' "$g\vaka_${Et}.json" {
  python tools\kitap\kilavuz_v2\yoklama\vaka_kos.py kos --uxb "bin\$Ik" --cikti "$g\vaka_${Et}.json" --is 6 *> "$g\vaka_${Et}.log"
}
Adim 'tarif' "$g\tarif_${Et}.txt" {
  foreach ($h in @(@('1007', 'uxb_kilavuz_20261007.exe'), @($Et, $Ik))) {
    if (Test-Path "$g\tarif_$($h[0]).txt") { G "tarif $($h[0]) zaten var"; continue }
    pwsh -NoProfile -File tools\kitap\kilavuz_v2\yoklama\tarif_dene.ps1 -Uxb "bin\$($h[1])" -Cikti "$env:TEMP\uxb_tarif_$($h[0])" *> "$g\tarif_$($h[0]).txt"
  }
}
Adim 'arac' "$g\arac_${Et}.json" {
  python tools\kitap\arac_dogrula.py --uxb "bin\$Ik" --sonuc "$g\arac_${Et}.json" *> "$g\arac_${Et}.log"
}
Adim 'kararlilik' "$g\kararlilik_taskgroup_${Et}.txt" {
  foreach ($ornek in @('20_esz\mutex', '53_kv_gorev\paralel_asal_sayim', '04_gorev\taskgroup')) {
    foreach ($h in @(@('1007', 'uxb_kilavuz_20261007.exe'), @($Et, $Ik))) {
      $ad = $ornek.Replace('\', '_')
      $cik = "$g\kararlilik_${ad}_$($h[0]).txt"
      if (Test-Path $cik) { continue }
      python tools\kitap\kilavuz_v2\yoklama\kararlilik.py --uxb "bin\$($h[1])" --dosya "docs\kitaplar\_ortak\ornekler\$ornek.uxb" --motor MIR --kez 10 --sure 90 *> $cik
    }
  }
  'bitti' | Set-Content "$g\kararlilik_taskgroup_${Et}.txt"
}
Adim 'x64a' $null {
  foreach ($h in @(@($Et, $Ik), @('1007', 'uxb_kilavuz_20261007.exe'))) {
    if (Test-Path "$g\vaka_x64a_$($h[0]).json") { G "x64a $($h[0]) zaten var"; continue }
    python tools\kitap\kilavuz_v2\yoklama\vaka_kos.py kos --uxb "bin\$($h[1])" --cikti "$g\vaka_x64a_$($h[0]).json" --motor x64a --sadece .iddia.json --is 5 *> "$g\vaka_x64a_$($h[0]).log"
  }
}
Adim 'astx64' "$g\ornek_astx64_$Et.json" {
  python tools\kitap\kilavuz_v2\yoklama\ornek_astx64.py --uxb "bin\$Ik" --sonuc "$g\ornek_astx64_$Et.json" --is 4 *> "$g\ornek_astx64_$Et.log"
}
Adim 'cli' "$sp\cli_$Et\rapor.md" {
  python tools\kitap\kilavuz_v2\yoklama\cli_secenek_tarama.py --uxb "bin\$Ik" --cikti "$sp\cli_$Et" --is 4 *> "$g\cli_$Et.log"
}
Adim 'model' "$g\model_${Et}.md" {
  & '.\tests\run_all_model_tests.ps1' -Uxb ".\bin\$Ik" -ReportPath "$g\model_${Et}.md" *> "$g\model_${Et}.log"
}
G 'HAT BİTTİ'

